function extractTextFromProviderPayload(value) {
  if (typeof value === 'string') {
    return value;
  }
  if (Array.isArray(value)) {
    return value
      .map((entry) => {
        if (typeof entry === 'string') return entry;
        if (!entry || typeof entry !== 'object') return '';
        if (typeof entry.text === 'string') return entry.text;
        if (typeof entry.content === 'string') return entry.content;
        if (entry.type === 'text' && typeof entry.value === 'string') return entry.value;
        return '';
      })
      .filter(Boolean)
      .join('');
  }
  if (value && typeof value === 'object') {
    if (typeof value.text === 'string') return value.text;
    if (typeof value.content === 'string') return value.content;
  }
  return '';
}

function buildAbortableRunHandle(abortController) {
  const state = {
    exitCode: null,
    killed: false,
    pid: null,
    kill(signal = 'SIGTERM') {
      if (state.killed || state.exitCode !== null) return false;
      state.killed = true;
      state.exitCode = signal === 'SIGKILL' ? 137 : 143;
      try {
        abortController.abort();
      } catch (_error) {
        // no-op
      }
      return true;
    }
  };
  return state;
}

require('./routes/auth')(app, {
  db,
  notify,
  truncateForNotify,
  requireAuth,
  getUserNotificationSettings,
  getRestartStatusPayload,
  updateUserNotificationSettingsStmt,
  sanitizeDiscordWebhookUrl,
  defaultWebhookUrl,
  parseBooleanSetting,
});

app.get('/api/devices/steamdeck/config', requireAuth, (req, res) => {
  const safeUserId = getSafeUserId(req.session.userId);
  if (!safeUserId) {
    return res.status(400).json({ error: 'user_id inválido' });
  }
  try {
    const config = getSteamDeckConfigForUser(safeUserId);
    return res.json({
      ok: true,
      enabled: steamDeckSshFeatureEnabled,
      config
    });
  } catch (error) {
    const statusCode = Number.isInteger(error && error.statusCode) ? error.statusCode : 500;
    return res.status(statusCode).json({
      error:
        error && error.exposeToClient
          ? error.message
          : `No se pudo leer configuración Steam Deck: ${truncateForNotify(error && error.message ? error.message : 'steamdeck_config_read_failed', 220)}`

